32	/**
33	 * Helper to format the policy denial error.
34	 */
35	export function getPolicyDenialError(
36	  config: Config,
37	  rule?: PolicyRule,
38	): { errorMessage: string; errorType: ToolErrorType } {
39	  const denyMessage = rule?.denyMessage ? ` ${rule.denyMessage}` : '';
40	  return {
41	    errorMessage: `Tool execution denied by policy.${denyMessage}`,
42	    errorType: ToolErrorType.POLICY_VIOLATION,
43	  };
44	}
45	
46	/**
47	 * Queries the system PolicyEngine to determine tool allowance.
48	 * @returns The PolicyDecision.
49	 * @throws Error if policy requires ASK_USER but the CLI is non-interactive.
50	 */
51	export async function checkPolicy(
52	  toolCall: ValidatingToolCall,
53	  config: Config,
54	): Promise<CheckResult> {
55	  const serverName =
56	    toolCall.tool instanceof DiscoveredMCPTool
57	      ? toolCall.tool.serverName
58	      : undefined;
59	
60	  const toolAnnotations = toolCall.tool.toolAnnotations;
61	
62	  const result = await config
63	    .getPolicyEngine()
64	    .check(
65	      { name: toolCall.request.name, args: toolCall.request.args },
66	      serverName,
67	      toolAnnotations,
68	    );
69	
70	  const { decision } = result;
71	
72	  // If the tool call was initiated by the client (e.g. via a slash command),
73	  // we treat it as implicitly confirmed by the user and bypass the
74	  // confirmation prompt if the policy engine's decision is 'ASK_USER'.
75	  if (
76	    decision === PolicyDecision.ASK_USER &&
77	    toolCall.request.isClientInitiated
78	  ) {
79	    return {
80	      decision: PolicyDecision.ALLOW,
81	      rule: result.rule,
82	    };
83	  }
84	
85	  /*
86	   * Return the full check result including the rule that matched.
87	   * This is necessary to access metadata like custom deny messages.
88	   */
89	  if (decision === PolicyDecision.ASK_USER) {
90	    if (!config.isInteractive()) {
91	      throw new Error(
92	        `Tool execution for "${
93	          toolCall.tool.displayName || toolCall.tool.name
94	        }" requires user confirmation, which is not supported in non-interactive mode.`,
95	      );
96	    }
97	  }
98	
99	  return {
100	    decision,
101	    rule: result.rule,
102	  };
103	}
