105	/**
106	 * Evaluates the outcome of a user confirmation and dispatches
107	 * policy config updates.
108	 */
109	export async function updatePolicy(
110	  tool: AnyDeclarativeTool,
111	  outcome: ToolConfirmationOutcome,
112	  confirmationDetails: SerializableConfirmationDetails | undefined,
113	  deps: {
114	    config: Config;
115	    messageBus: MessageBus;
116	    toolInvocation?: AnyToolInvocation;
117	  },
118	): Promise<void> {
119	  // Mode Transitions (AUTO_EDIT)
120	  if (isAutoEditTransition(tool, outcome)) {
121	    deps.config.setApprovalMode(ApprovalMode.AUTO_EDIT);
122	    return;
123	  }
124	
125	  // Determine persist scope if we are persisting.
126	  let persistScope: 'workspace' | 'user' | undefined;
127	  if (outcome === ToolConfirmationOutcome.ProceedAlwaysAndSave) {
128	    // If folder is trusted and workspace policies are enabled, we prefer workspace scope.
129	    if (
130	      deps.config.isTrustedFolder() &&
131	      deps.config.getWorkspacePoliciesDir() !== undefined
132	    ) {
133	      persistScope = 'workspace';
134	    } else {
135	      persistScope = 'user';
136	    }
137	  }
138	
139	  // Specialized Tools (MCP)
140	  if (confirmationDetails?.type === 'mcp') {
141	    await handleMcpPolicyUpdate(
142	      tool,
143	      outcome,
144	      confirmationDetails,
145	      deps.messageBus,
146	      persistScope,
147	    );
148	    return;
149	  }
150	
151	  // Generic Fallback (Shell, Info, etc.)
152	  await handleStandardPolicyUpdate(
153	    tool,
154	    outcome,
155	    confirmationDetails,
156	    deps.messageBus,
157	    persistScope,
158	    deps.toolInvocation,
159	    deps.config,
160	  );
161	}
162	
163	/**
164	 * Returns true if the user's 'Always Allow' selection for a specific tool
165	 * should trigger a session-wide transition to AUTO_EDIT mode.
166	 */
167	function isAutoEditTransition(
168	  tool: AnyDeclarativeTool,
169	  outcome: ToolConfirmationOutcome,
170	): boolean {
171	  // TODO: This is a temporary fix to enable AUTO_EDIT mode for specific
172	  // tools. We should refactor this so that callbacks can be removed from
173	  // tools.
174	  return (
175	    outcome === ToolConfirmationOutcome.ProceedAlways &&
176	    EDIT_TOOL_NAMES.has(tool.name)
177	  );
178	}
