180	/**
181	 * Handles policy updates for standard tools (Shell, Info, etc.), including
182	 * session-level and persistent approvals.
183	 */
184	async function handleStandardPolicyUpdate(
185	  tool: AnyDeclarativeTool,
186	  outcome: ToolConfirmationOutcome,
187	  confirmationDetails: SerializableConfirmationDetails | undefined,
188	  messageBus: MessageBus,
189	  persistScope?: 'workspace' | 'user',
190	  toolInvocation?: AnyToolInvocation,
191	  config?: Config,
192	): Promise<void> {
193	  if (
194	    outcome === ToolConfirmationOutcome.ProceedAlways ||
195	    outcome === ToolConfirmationOutcome.ProceedAlwaysAndSave
196	  ) {
197	    const options: PolicyUpdateOptions =
198	      toolInvocation?.getPolicyUpdateOptions?.(outcome) || {};
199	
200	    if (!options.commandPrefix && confirmationDetails?.type === 'exec') {
