45	  options: AgentSchedulingOptions,
46	): Promise<CompletedToolCall[]> {
47	  const {
48	    schedulerId,
49	    parentCallId,
50	    toolRegistry,
51	    signal,
52	    getPreferredEditor,
53	    onWaitingForConfirmation,
54	  } = options;
55	
56	  // Create a proxy/override of the config to provide the agent-specific tool registry.
57	  // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
58	  const agentConfig: Config = Object.create(config);
59	  agentConfig.getToolRegistry = () => toolRegistry;
60	  agentConfig.getMessageBus = () => toolRegistry.getMessageBus();
61	  // Override toolRegistry property so AgentLoopContext reads the agent-specific registry.
62	  Object.defineProperty(agentConfig, 'toolRegistry', {
63	    get: () => toolRegistry,
64	    configurable: true,
65	  });
66	
67	  const scheduler = new Scheduler({
68	    config: agentConfig,
69	    messageBus: toolRegistry.getMessageBus(),
70	    getPreferredEditor: getPreferredEditor ?? (() => undefined),
71	    schedulerId,
72	    parentCallId,
73	    onWaitingForConfirmation,
74	  });
75	
